//! Desktop application (egui/eframe).

pub mod app;
pub mod float_panel;
pub mod theme;
pub mod tray;
pub mod widgets;

pub use app::ScreenRecApp;

/// The application icon, embedded at compile time.
///
/// `assets/icon.png` is generated by `cargo run --example make_icon`; the
/// `.ico` next to it is what [`build.rs`] embeds into the executable, so
/// Explorer and the taskbar show the same artwork as the window.
const ICON_PNG: &[u8] = include_bytes!("../../assets/icon.png");

/// Decodes the embedded icon into the form egui wants.
///
/// A missing or unreadable icon must not stop the application from starting, so
/// failures are logged and the default window icon is kept.
fn window_icon() -> Option<egui::IconData> {
    match image::load_from_memory(ICON_PNG) {
        Ok(image) => {
            let image = image.into_rgba8();
            let (width, height) = image.dimensions();
            Some(egui::IconData {
                rgba: image.into_raw(),
                width,
                height,
            })
        }
        Err(err) => {
            log::warn!("应用图标解码失败，使用默认图标：{err}");
            None
        }
    }
}

/// Runs the desktop application.
pub fn run() -> anyhow::Result<()> {
    let log_path = crate::logging::init_for_gui();
    if let Some(path) = &log_path {
        log::info!("启动界面，日志：{}", path.display());
    }

    let mut viewport = egui::ViewportBuilder::default()
        .with_title("ScreenRec — 屏幕录制")
        .with_inner_size([1060.0, 720.0])
        .with_min_inner_size([880.0, 600.0]);
    if let Some(icon) = window_icon() {
        viewport = viewport.with_icon(std::sync::Arc::new(icon));
    }

    let options = eframe::NativeOptions {
        viewport,
        ..Default::default()
    };

    eframe::run_native(
        "ScreenRec",
        options,
        Box::new(|cc| Ok(Box::new(ScreenRecApp::new(cc)))),
    )
    .map_err(|err| anyhow::anyhow!("{err}"))
}

/// Reports a fatal startup problem in a message box, since a GUI build has no
/// console to print to.
pub fn show_fatal_error(message: &str) {
    use windows::core::HSTRING;
    use windows::Win32::UI::WindowsAndMessaging::{
        MessageBoxW, MB_ICONERROR, MB_OK, MB_SETFOREGROUND,
    };

    let text = HSTRING::from(message);
    let caption = HSTRING::from("ScreenRec 启动失败");
    unsafe {
        MessageBoxW(None, &text, &caption, MB_OK | MB_ICONERROR | MB_SETFOREGROUND);
    }
}
